import{_ as o,o as t,c as l,a5 as p}from"./chunks/framework.BPFk9-tb.js";const b=JSON.parse('{"title":"写作课作业-081","description":"","frontmatter":{"date":"2020-10-22T19:35:25","title":"写作课作业-081","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/081.md","filePath":"posts/homework/081.md"}'),a={name:"posts/homework/081.md"};function c(r,e,i,s,u,k){return t(),l("div",null,[...e[0]||(e[0]=[p('<blockquote><p>10.8 写作作业：《微信互联网平民创业》之《13. 打造广场之前如何打地基?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>如果说，微信朋友圈是个「大屏幕」，那么，微信通讯录就好像是「挂着那块大屏幕的承重墙」;如果说，微信是个「大广场」，那么，微信通讯录就好像是「那广场的地 面」...... 那么，请问，「地基」是什么呢?</p><p>你这个人才是真正的地基啊......</p></blockquote><blockquote><p>不仅从商业⻆度，更是从人生⻆度，这个问题有个最硬核的标准答案:</p><p>成为一个值得信赖的人。</p></blockquote><blockquote><p>坚持这样的原则、坚守这样的底线，其实根本就不需要得罪人，不需要触碰政治红线， 更不需要「卧薪尝胆」什么的，甚至，干脆就不可能因此与任何人发生冲突，只需要付出时间和精力，努力与自己死磕，甚至拼命。</p></blockquote><blockquote><p>虽然「有原则有底线」其实可以并不难，但，有一点是非常难的，也只能很难很难好， 那就是不仅要「有原则有底线」，还要「⻓期有原则有底线」—— 反正，「⻓期」两个 字，放在任何地方，古今中外，都是少有人能够做到的。</p></blockquote><blockquote><p>所谓的「信赖」，是「信任」+「依赖」。那，那些信任你的人凭什么竟然会「依赖」你呢?首先，没有信任，就不可能有依赖。而后，如果你是有原则有底线的值得他人信任的人，再加上另外一点就够了:</p><p>专业</p><p>—— 那么，「信任」你的人会进而「信赖」你。</p></blockquote><blockquote><p>所谓的「专业」或「突出」只是一个习惯而已，一个可以养成的习惯。很小的时候，我父亲教我说，「你要学会时不时做出让大家佩服的事情。」—— 然后这句话我受用终生...... 所以才会有很多事情发生。</p></blockquote><blockquote><p>记住，无论做什么事情，都应该更「专业」一点 —— 只要养成这个习惯就好。其实， 「比大多数人更专业」实在是再简单不过的事情，不管做什么，养成以下三个好习惯:</p><ul><li>开始之前做足准备工作;</li><li>过程之中全力以赴;</li><li>结束的时候做足收尾工作......</li></ul></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>之前笑来老师说，成为能说那话的人，那怎么成为呢？其实也给了答案：只需要付出时间和精力，努力与自己死磕，甚至拼命，成为一个值得信赖的人。</p><blockquote><p>所谓的「专业」或「突出」只是一个习惯而已，一个可以养成的习惯。很小的时候，我父亲教我说，「你要学会时不时做出让大家佩服的事情。」—— 然后这句话我受用终生...... 所以才会有很多事情发生。</p></blockquote><p>在写作课中，笑来老师对“超级专业”有专门的一讲——做得久，想得深，干得狠。</p><p>有时候困惑自己怎么不敢开启销售呢？其实是自己的地基没有打好，在投资知识上，在服务的环节上的时间投入不够。嗯，实际就是自己懒和傻罢了。</p><p>因为“超级专业”这个词，反思自己的工作和学习，是否有足够的投入，投入是否有效。</p>',15)])])}const q=o(a,[["render",c]]);export{b as __pageData,q as default};
